"""Presentation-ready TraceTrust dashboard."""

from fastapi.responses import HTMLResponse


def dashboard() -> HTMLResponse:
    html = '''<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>TraceTrust · Visual Analytics</title>
<style>
:root{--ink:#15213b;--muted:#64748b;--bg:#f2f6fb;--line:#dfe7f2;--blue:#315efb;--cyan:#35b7d8;--green:#11845b;--red:#c24132}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.45 Inter,system-ui,sans-serif}header{background:radial-gradient(circle at 78% 20%,#3764c4 0,#213d79 36%,#111d37 100%);color:#fff;padding:34px max(24px,calc((100% - 1280px)/2));display:flex;justify-content:space-between;align-items:end}header h1{margin:0 0 6px;font-size:34px}.subtle{color:var(--muted)}header .subtle{color:#d6e0ff}.badge{border:1px solid #ffffff42;border-radius:999px;padding:8px 12px;color:#e5edff}.wrap{max-width:1280px;margin:26px auto;padding:0 24px}.toolbar{display:flex;gap:12px;align-items:end;flex-wrap:wrap;margin-bottom:18px}label{display:flex;flex-direction:column;gap:5px;color:var(--muted);font-size:12px;font-weight:700}select,button{border:1px solid #cbd7e6;border-radius:10px;padding:10px 12px;background:#fff;color:var(--ink);font:inherit}button{background:var(--blue);color:#fff;border:0;cursor:pointer;font-weight:700}.hint{margin-left:auto;color:var(--muted);font-size:12px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.card{background:#fff;border:1px solid var(--line);border-radius:16px;padding:18px;box-shadow:0 8px 24px #182b4d0b}.metric{font-size:30px;font-weight:800;margin-top:7px}.label{font-size:12px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}.score{color:var(--green)}.layout{display:grid;grid-template-columns:1.35fr .85fr;gap:16px;margin-top:16px}.card h2{margin:0 0 6px;font-size:18px}.graph-toolbar{display:flex;gap:7px;align-items:center;margin:12px 0;color:var(--muted);font-size:12px}.graph-toolbar button{padding:6px 10px;background:#eef3ff;color:var(--blue);font-size:12px}.graph-wrap{height:390px;border-radius:12px;background:linear-gradient(135deg,#f8fbff,#eef5ff);overflow:hidden;border:1px solid #e2eaf5}.graph-wrap svg{width:100%;height:100%;display:block}.edge{stroke:#9db2d0;stroke-width:1.4;opacity:.72}.edge.match{stroke:#8b74e8;stroke-dasharray:5 4}.node{cursor:pointer;filter:drop-shadow(0 2px 3px #25416b22)}.node-label{font-size:10px;fill:#3a4b68;pointer-events:none;font-weight:600}.lane-label{font-size:10px;fill:#64748b;font-weight:800;letter-spacing:.08em}.legend{display:flex;gap:14px;flex-wrap:wrap;margin-top:10px;color:var(--muted);font-size:12px}.legend i{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:5px}.timeline{display:flex;gap:10px;overflow:auto;padding:12px 2px}.event{min-width:155px;border:1px solid var(--line);border-radius:12px;padding:12px;background:#fbfcff}.event:before{content:"";display:block;height:3px;border-radius:9px;background:linear-gradient(90deg,var(--blue),var(--cyan));margin:-12px -12px 10px}.event strong{display:block}.event small{color:var(--muted)}.factor{margin:12px 0}.factor-head{display:flex;justify-content:space-between}.bar{height:8px;background:#e9eef7;border-radius:10px;overflow:hidden;margin-top:6px}.bar i{display:block;height:100%;background:linear-gradient(90deg,#4a73ff,#6fb8ff)}.finding{display:flex;justify-content:space-between;gap:12px;border-top:1px solid var(--line);padding:11px 0}.high,.critical{color:var(--red);font-weight:700}.medium{color:#c27a18;font-weight:700}.empty{display:grid;place-items:center;height:100%;color:var(--muted)}@media(max-width:900px){.grid{grid-template-columns:repeat(2,1fr)}.layout{grid-template-columns:1fr}.hint{margin-left:0}}@media(max-width:520px){.grid{grid-template-columns:1fr}header{display:block}.badge{display:inline-block;margin-top:16px}}
</style></head><body><header><div><h1>TraceTrust</h1><div class="subtle">Visual analytics para trazabilidad agroindustrial</div></div><div class="badge">Grafo vivo · auditable · explicable</div></header>
<main class="wrap"><div class="toolbar"><label>Snapshot<select id="snapshot"></select></label><label>Lote<select id="lot"></select></label><button onclick="refresh()">Actualizar análisis</button><span class="hint">Selecciona un nodo para inspeccionar su contexto</span></div><section class="grid" id="metrics"></section>
<div class="layout"><section class="card"><h2>Mapa de trazabilidad</h2><p class="subtle">El lote seleccionado se conecta con sus eventos, evidencias y hallazgos</p><div class="graph-toolbar"><button onclick="zoom(1.15)">＋ Zoom</button><button onclick="zoom(.87)">− Zoom</button><button onclick="fitGraph()">Centrar</button><span id="graph-info"></span></div><div class="graph-wrap"><svg id="graph" viewBox="0 0 900 390" role="img" aria-label="Grafo de trazabilidad"></svg></div><div class="legend"><span><i style="background:#315efb"></i>Lote</span><span><i style="background:#35b7d8"></i>Evento</span><span><i style="background:#7856d6"></i>Evidencia</span><span><i style="background:#c24132"></i>Hallazgo</span></div></section><section class="card"><h2>Trust Score explicable</h2><div id="score"></div><div id="factors"></div></section></div>
<div class="layout"><section class="card"><h2>Historia del lote</h2><p class="subtle">Secuencia temporal reconstruida desde el grafo</p><div class="timeline" id="timeline"></div></section><section class="card"><h2>Hallazgos y anomalías</h2><div id="findings"></div></section></div></main>
<script>
let snapshot='',graphData=null,scale=1,selected='',mode='detail';const $=id=>document.getElementById(id);
async function get(path){const r=await fetch(path);if(!r.ok)throw Error(await r.text());return r.json()}
function esc(v){return String(v??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]))}
function color(type){return type==='lot'?'#315efb':type==='event'?'#35b7d8':type==='evidence'?'#7856d6':type==='finding'?'#c24132':'#94a3b8'}
function renderGlobal(){
  mode='global';if(!graphData)return;const svg=$('graph'),lots=graphData.nodes.filter(n=>n.node_type==='lot'&&n.properties.snapshot_id===snapshot),findings=graphData.nodes.filter(n=>n.node_type==='finding'&&n.properties.snapshot_id===snapshot),nodes=[...lots,...findings],pos={};
  lots.forEach((n,i)=>pos[n.id]={x:130+(i%4)*150,y:58+Math.floor(i/4)*62});findings.forEach((n,i)=>pos[n.id]={x:760,y:42+i*30});
  svg.innerHTML='<defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="3" orient="auto"><path d="M0,0 L8,3 L0,6 z" fill="#9db2d0"/></marker></defs><text class="lane-label" x="105" y="20">LOTES DEL SNAPSHOT</text><text class="lane-label" x="710" y="20">HALLAZGOS</text>';
  const edges=graphData.edges.filter(e=>pos[e.source]&&pos[e.target]);svg.innerHTML+=edges.map(e=>{const a=pos[e.source],b=pos[e.target];return `<line class="edge" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" marker-end="url(#arrow)"/>`}).join('');
  svg.innerHTML+=nodes.map(n=>{const p=pos[n.id],fill=color(n.node_type);return `<g data-global-node="${esc(n.id)}" data-lot="${n.node_type==='lot'?esc(n.label):''}"><circle class="node" cx="${p.x}" cy="${p.y}" r="${n.node_type==='lot'?14:9}" style="fill:${fill};stroke:#fff;stroke-width:2.5px"/><text class="node-label" x="${p.x+18}" y="${p.y+4}">${esc((n.label||n.id).slice(0,24))}</text></g>`}).join('');
  $('graph-info').textContent=`Vista global · ${lots.length} lotes · ${findings.length} hallazgos`;
  const average=$('metrics').querySelector('.score')?.textContent?.trim()||'—';
  $('score').innerHTML=`<div class="metric score">${average??'—'} / 100</div><p class="subtle">Trust Score promedio del snapshot seleccionado. Selecciona un lote para ver su puntuación individual y los factores explicables.</p>`;
  $('factors').innerHTML='<div class="empty" style="min-height:120px">Vista global · selecciona un lote para inspeccionar sus factores</div>';
  svg.querySelectorAll('g[data-global-node][data-lot]').forEach(el=>el.addEventListener('click',()=>{if(!el.dataset.lot)return;$('lot').value=el.dataset.lot;mode='detail';refresh()}));
}
function renderGraph(focus){
  if(!graphData)return;
  const root=`lot:${snapshot}:${focus}`,adj=new Map();
  graphData.edges.forEach(e=>{if(!adj.has(e.source))adj.set(e.source,[]);if(!adj.has(e.target))adj.set(e.target,[]);adj.get(e.source).push(e.target);adj.get(e.target).push(e.source)});
  const keep=new Set([root]);let front=[root];for(let depth=0;depth<2;depth++){const next=[];front.forEach(id=>(adj.get(id)||[]).forEach(n=>{if(!keep.has(n)){keep.add(n);next.push(n)}}));front=next}
  const supported=['lot','event','evidence','finding'];let nodes=graphData.nodes.filter(n=>keep.has(n.id)&&supported.includes(n.node_type));if(!nodes.length)nodes=graphData.nodes.filter(n=>supported.includes(n.node_type)).slice(0,30);
  const cols={lot:100,event:325,evidence:560,finding:785},names={lot:'LOTES',event:'EVENTOS',evidence:'EVIDENCIAS',finding:'HALLAZGOS'},pos={},by={};supported.forEach(t=>by[t]=nodes.filter(n=>n.node_type===t));
  supported.forEach(t=>by[t].forEach((n,i)=>pos[n.id]={x:cols[t],y:48+i*Math.max(42,290/Math.max(1,by[t].length-1))}));
  const svg=$('graph');svg.innerHTML='<defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="3" orient="auto"><path d="M0,0 L8,3 L0,6 z" fill="#9db2d0"/></marker></defs>'+supported.map(t=>`<text class="lane-label" x="${cols[t]-40}" y="20">${names[t]}</text>`).join('');
  const edges=graphData.edges.filter(e=>pos[e.source]&&pos[e.target]);svg.innerHTML+=edges.map(e=>{const a=pos[e.source],b=pos[e.target];return `<line class="edge ${e.relation==='reconciles_with'?'match':''}" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" marker-end="url(#arrow)"/>`}).join('');
  svg.innerHTML+=nodes.map(n=>{const p=pos[n.id],active=n.id===root||n.id===selected,fill=color(n.node_type);return `<g data-node="${esc(n.id)}"><circle class="node" cx="${p.x}" cy="${p.y}" r="${active?13:9}" style="fill:${fill};stroke:${active?'#111d37':'#ffffff'};stroke-width:${active?4:2.5}px"/><text class="node-label" x="${p.x+16}" y="${p.y+4}">${esc((n.label||n.id).slice(0,24))}</text></g>`}).join('');
  $('graph-info').textContent=`${nodes.length} nodos · ${edges.length} relaciones`;svg.querySelectorAll('g[data-node]').forEach(el=>el.addEventListener('click',()=>{selected=el.dataset.node;renderGraph(focus)}));svg.style.transform=`scale(${scale})`;svg.style.transformOrigin='center';
}
function zoom(f){scale=Math.max(.7,Math.min(1.8,scale*f));$('graph').style.transform=`scale(${scale})`}function fitGraph(){scale=1;$('graph').style.transform='scale(1)'}
async function boot(){const d=await get('/api/v1/snapshots');$('snapshot').innerHTML=d.items.map(x=>`<option value="${esc(x.snapshot_id)}">${esc(x.snapshot_id)}</option>`).join('');snapshot=$('snapshot').value;await loadLots()}
async function loadLots(){const d=await get(`/api/v1/snapshots/${snapshot}/lots?limit=100`);$('lot').innerHTML=d.items.map(x=>`<option value="${esc(x.lot_id)}">${esc(x.lot_id)} · ${x.trust_score??'—'}</option>`).join('');await refresh()}
async function refresh(){snapshot=$('snapshot').value;const lot=$('lot').value;if(!lot)return;const[s,t,l,f,g]=await Promise.all([get(`/api/v1/snapshots/${snapshot}`),get(`/api/v1/trust/${snapshot}/${lot}`),get(`/api/v1/lots/${snapshot}/${lot}/lineage?direction=both&depth=5`),get(`/api/v1/findings/${snapshot}?limit=100`),get(`/api/v1/snapshots/${snapshot}/graph`)]);graphData=g;selected=`lot:${snapshot}:${lot}`;$('metrics').innerHTML=`<div class="card"><div class="label">Eventos</div><div class="metric">${s.event_count}</div></div><div class="card"><div class="label">Lotes</div><div class="metric">${s.lot_count}</div></div><div class="card"><div class="label">Hallazgos</div><div class="metric">${s.finding_count}</div></div><div class="card"><div class="label">Trust promedio</div><div class="metric score">${s.average_trust_score??'—'}</div></div>`;$('score').innerHTML=`<div class="metric score">${t.score.toFixed(2)} / 100</div><p class="subtle">${esc(t.explanation)}</p>`;$('factors').innerHTML=t.factors.map(x=>`<div class="factor"><div class="factor-head"><span>${esc(x.name)}</span><strong>${(x.score*100).toFixed(1)}%</strong></div><div class="bar"><i style="width:${x.score*100}%"></i></div></div>`).join('');const nodes=[...(l.ancestors?.nodes||[]),...(l.descendants?.nodes||[])].filter((n,i,a)=>n.node_type==='event'&&a.findIndex(x=>x.id===n.id)===i).sort((a,b)=>String(a.properties.timestamp).localeCompare(String(b.properties.timestamp)));$('timeline').innerHTML=nodes.map(n=>`<div class="event"><strong>${esc(n.properties.event_type)}</strong><small>${esc(n.label)}</small><br><small>${esc(n.properties.timestamp)}</small><br><small>${esc(n.properties.quantity)} ${esc(n.properties.unit)}</small></div>`).join('')||'<div class="empty">Sin eventos</div>';const relevant=f.items.filter(x=>x.entity_ids.includes(lot));$('findings').innerHTML=relevant.map(x=>`<div class="finding"><span>${esc(x.rule_id)}<br><small class="subtle">${esc(x.explanation)}</small></span><strong class="${x.severity}">${esc(x.severity)}</strong></div>`).join('')||'<div class="empty">No hay hallazgos para este lote</div>';renderGraph(lot)}
document.addEventListener('DOMContentLoaded',()=>{const globalButton=document.createElement('button');globalButton.textContent='Vista global';globalButton.onclick=renderGlobal;document.querySelector('.graph-toolbar').prepend(globalButton);$('snapshot').addEventListener('change',async()=>{snapshot=$('snapshot').value;await loadLots()});$('lot').addEventListener('change',refresh);boot()});
</script></body></html>'''
    return HTMLResponse(html)
